import { AnimationStateListener, Event, EventTimeline, SkeletonData, Spine, TrackEntry } from '@esotericsoftware/spine-pixi-v8';
import { Ticker } from 'pixi.js';

import { SoundGroupController } from './sound-group-controller';
import { SoundManager } from './sound-manager';
import { IAudioPath, IMusicSpineAction, IMusicSpineSoundData, ISoundStartingInfo } from './types';

const delay = (ms: number): Promise<void> => new Promise<void>(
    (resolve) => setTimeout(resolve, ms)
);

export class MusicSpine extends Spine {
    protected trackListeners!: AnimationStateListener;
    protected lastPerformanceMS: number = -1;
    protected performanceMS: number = 0;
    protected soundTrackMap: Map<number, Map<string, IMusicSpineSoundData>> = new Map();
    protected updateOnce: boolean = false;
    private mCanUpdate: boolean = false;
    private trackMasterVolume: Map<number, number> = new Map();
    private ticker!: Ticker;

    public get canUpdate(): boolean { return this.mCanUpdate || this.updateOnce; }

    protected set canUpdate(value: boolean) {
        if (!this.canUpdate && value) { this.resetPerformanceMS(); }
        this.mCanUpdate = value;
    }

    public constructor(spineData: SkeletonData, protected readonly soundManager: SoundManager, ticker?: Ticker) {
        super(spineData);
        this.setupUpdate(ticker ?? Ticker.shared);
        this.trackUpdateListener();
        this.audioEventListener();
    }

    public update(): void {
        // Freeze the timeline while the tab is hidden. The ticker (rAF) is paused/throttled
        // by the browser and the audio context is suspended, so advancing here would only
        // build up a large elapsed gap that gets fast-forwarded on the next visible frame.
        if (!this.canUpdate || !this.soundManager.isUnlocked) { return; }
        this.updateOnce = false;
        this.updatePerformanceMS();
        this.checkPlaybackSpeed();
        super.update(this.performanceMS * 0.001);
    }

    /**
     * @description forces the spine to be updated the next time UISpine updates
     */
    public forceSpineUpdate(): void {
        if (!this.canUpdate) {
            if (!this.updateOnce) { this.resetPerformanceMS(); }
            this.updateOnce = true;
        }
    }

    private setupUpdate(ticker: Ticker): void {
        this.ticker = ticker;
        ticker.add(this.update, this);
    }

    public destroy(options?: Parameters<Spine['destroy']>[0]): void {
        this.ticker.remove(this.update, this);
        this.soundManager.off('isUnlocked', this.onUnlock, this);
        super.destroy(options);
    }

    protected trackUpdateListener(): void {
        this.state.removeListener(this.trackListeners);

        const checkTurnOffUpdate = () => {
            // track has a method isComplete that it hasn't got the definitions for
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            this.canUpdate = this.state.tracks.some((track) => track && (track.loop || !track.isComplete()));
            if (!this.canUpdate) { this.resetPerformanceMS(); }
        };

        this.trackListeners = {
            start: () => { this.canUpdate = true; },
            end: () => { checkTurnOffUpdate(); },
            complete: (track: TrackEntry) => { if (!track.loop) checkTurnOffUpdate(); }
        };

        this.state.addListener(this.trackListeners);
    }

    protected updatePerformanceMS(): void {
        const performanceNow = performance.now();

        if (this.lastPerformanceMS < 0) {
            this.lastPerformanceMS = performanceNow;
            this.performanceMS = 0;
        } else {
            this.performanceMS = performanceNow - this.lastPerformanceMS;
            this.lastPerformanceMS = performanceNow;
        }
    }

    protected resetPerformanceMS(): void {
        this.lastPerformanceMS = -1;
    }

    protected getTrackMap(trackIndex: number): Map<string, IMusicSpineSoundData> {
        return this.soundTrackMap.get(trackIndex) ?? this.soundTrackMap.set(trackIndex, new Map()).get(trackIndex) as Map<string, IMusicSpineSoundData>;
    }

    protected resetTrackMap(trackIndex: number): void {
        this.soundTrackMap.set(trackIndex, new Map());
    }

    protected getTrackSound(trackIndex: number, category: string, name: string): IMusicSpineSoundData;
    protected getTrackSound(trackIndex: number, key: string): IMusicSpineSoundData;

    protected getTrackSound(trackIndex: number, category: string, name?: string): IMusicSpineSoundData {
        const trackMap = this.getTrackMap(trackIndex);
        const key = name ? `${category}:${name}` : category;

        category = name ? category : key.split(':')[0];
        name = name ?? key.split(':')[1];
        return trackMap.get(key) ?? trackMap.set(key, { category, name, soundInstances: [] }).get(key) as IMusicSpineSoundData;
    }

    protected onUnlock(isUnlocked: boolean): void {
        if (!isUnlocked) {
            return;
        }
        this.resetPerformanceMS();
        this.state.tracks.forEach((track) => {
            if (track && track.trackTime > 0) {
                this.clearAllSoundsOnTrack(track);
                const timelines = track.animation!.timelines;
                const eventTimeline = timelines.find((timeline) => timeline instanceof EventTimeline) as EventTimeline | undefined;
                if (eventTimeline) {
                    eventTimeline.events.forEach((event) => this.onAudioEvent(track, event as Event));
                }
            }
        });
    }

    private audioEventListener(): void {
        this.soundManager.on('isUnlocked', this.onUnlock, this);

        this.state.addListener({
            event: (entry: TrackEntry, event: Event) => {
                this.emit('musicSpineEvent', { entry, event });
                if (event.data.audioPath && this.soundManager.isUnlocked) {
                    this.onAudioEvent(entry, event);
                }
            },
            interrupt: (entry) => {
                this.onTrackInterrupted(entry);
            },
            complete: (entry) => {
                this.clearAllSoundsOnTrack(entry);
            }
        });
    }

    /**
     * intended to be overwritten
     * @param category - string for the soundmanager category
     * @param sound - string for the sound to be played from the sound sprite
     * @returns an alternative category/sound based on the incoming data
     */
    protected getAudioPath(category: string, sound: string): IAudioPath {
        return { category, sound };
    }

    /**
     * intended to be overwritten
     * @param category - string for the soundmanager category
     * @param sound - string for the sound to be played from the sound sprite
     * @returns boolean - if true the sound will play, if false it will prevent the sound being played
     */
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    protected shouldPlaySound(_category: string, _sound: string): boolean {
        return true;
    }

    /**
     * intended to be overwritten
     * @param _soundStartData - data relating to the sound playing, including its initial playback offset
     * @param _action - regular expression match to get data for the action
     */
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    protected runAudioAction(_soundStartData: ISoundStartingInfo, _action: IMusicSpineAction): void {
        return;
    }

    public clearAllSoundsOnTrack(entry: TrackEntry): void {
        const trackMap = this.getTrackMap(entry.trackIndex);

        trackMap.forEach((soundData) => {
            soundData.soundInstances.forEach((instance) => {
                instance.dispose();
            });
            soundData.soundInstances.length = 0;
        });
        //finish off by resetting the track map
        this.resetTrackMap(entry.trackIndex);
    }

    /**
     * intended to be overwritten
     * @param entry - the track entry which has been interrupted
     */
    protected onTrackInterrupted(entry: TrackEntry): void {
        //default behaviour is to just stop all the current audio tracks and wipe the sound maps
        this.clearAllSoundsOnTrack(entry);
    }

    private onAudioEvent(entry: TrackEntry, event: Event): void {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const time = entry.trackTime;
        //event fired before possible
        if (time < event.time) { return; }

        const timeScale = entry.timeScale * this.state.timeScale;
        const loops = Math.floor(time / entry.animationEnd);
        const calculatedElapsedTime = time - (event.time + loops * entry.animationEnd);
        const elapsedTime = Math.max(0, calculatedElapsedTime);

        // magical regex which checks the event name is of format "soundCategory:soundName:?action"
        // with an optional extra match after the soundName if we want to perform a custom action
        const regex = new RegExp('^(?:.+\\/)?([^:\\s]+):([^:\\s]+)');
        const match = event.data.name.match(regex);
        if (match !== null) {
            //play the sound corresponding to that category and sound name
            const { category, sound } = this.getAudioPath(match[1], match[2]);
            if (!this.shouldPlaySound(category, sound)) {
                return;
            }

            const soundGroupController: SoundGroupController = category === 'music' ? this.soundManager.music : this.soundManager.sfx;

            const volume: number = (event.data.volume ?? 1) * (this.trackMasterVolume.get(entry.trackIndex) ?? 1);
            const soundInstance = soundGroupController.play(category, {
                sprite: sound,
                volume: volume,
                rate: timeScale,
                seek: elapsedTime,
                loop: false
            });
            if (!soundInstance || soundInstance.isDisposed) {
                return;
            }
            this.getTrackSound(entry.trackIndex, category, sound).soundInstances.push(soundInstance);
            soundInstance.once('dispose', () => {
                this.getTrackSound(entry.trackIndex, category, sound).soundInstances.remove(soundInstance);
            });

            const stringValue = event.data.stringValue;
            if (stringValue) {
                const actions = stringValue.split(':');
                this.runAudioAction({ soundInstance, data: event.data, elapsedTime }, { name: actions[0], args: actions.slice(1) });
            }
        }
    }

    private checkPlaybackSpeed(): void {
        this.soundTrackMap.forEach((sounds, trackIndex) => {
            const trackEntry = this.state.tracks[trackIndex];
            const timeScale = (trackEntry?.timeScale ?? 1) * this.state.timeScale;

            sounds.forEach((sound) => {
                sound.soundInstances.forEach((soundInstance) => {
                    if (soundInstance.isDisposed) {
                        return;
                    }
                    soundInstance.rate = timeScale;
                });
            });
        });
    }

    public async crossFadeTrack(fromTrack: number, toTrack: number, duration: number): Promise<void> {
        const startTime: number = performance.now();

        const endTime = startTime + (duration);

        let now = performance.now();

        while (now < endTime) {
            const percentage = (now - startTime) / duration;

            const fromTracks = this.getTrackMap(fromTrack);
            const toTracks = this.getTrackMap(toTrack);

            fromTracks.forEach((soundData) => {
                soundData.soundInstances.forEach((instance) => {
                    if (instance.isDisposed) {
                        return;
                    }
                    instance.volume = 1 - percentage;
                });
            });

            toTracks.forEach((soundData) => {
                soundData.soundInstances.forEach((instance) => {
                    if (instance.isDisposed) {
                        return;
                    }
                    instance.volume = percentage;
                });
            });

            this.trackMasterVolume.set(fromTrack, 1 - percentage);
            this.trackMasterVolume.set(toTrack, percentage);

            await delay(0);

            now = performance.now();
        }
    }

    public muteTrack(trackIndex: number): void {
        this.setTrackVolume(trackIndex, 0);
    }

    public setTrackVolume(trackIndex: number, volume: number): void {
        const tracks = this.getTrackMap(trackIndex);
        tracks.forEach((soundData) => {
            soundData.soundInstances.forEach((instance) => {
                if (instance.isDisposed) {
                    return;
                }
                instance.volume = volume;
            });
        });
        this.trackMasterVolume.set(trackIndex, volume);
    }
}